/* prog20_anagram_checker.c
 *
 * Re‑implementation of the original binary’s functionality.
 * The program expects exactly two command‑line arguments.
 *
 *   - If the number of arguments is wrong, it prints "USAGE".
 *   - If either argument is longer than 1024 characters, it prints "TOO_LONG".
 *   - Otherwise it checks whether the two strings are anagrams of each other,
 *     ignoring spaces and treating letters case‑insensitively.
 *     It prints "ANAGRAM" when they are anagrams, otherwise "NOT_ANAGRAM".
 *
 * The output strings match the exact literals used in the original binary.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN 1024   /* 0x400 bytes, the limit used by the original program */

int main(int argc, char *argv[])
{
    /* -------------------------------------------------------------------- */
    /* Argument count handling                                               */
    /* -------------------------------------------------------------------- */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *s1 = argv[1];
    const char *s2 = argv[2];

    /* -------------------------------------------------------------------- */
    /* Length checks (both strings must be < 1025 characters)               */
    /* -------------------------------------------------------------------- */
    if (strlen(s1) > MAX_LEN || strlen(s2) > MAX_LEN) {
        puts("TOO_LONG");
        return 0;
    }

    /* -------------------------------------------------------------------- */
    /* Frequency tables (256 entries, one per possible byte value)          */
    /* -------------------------------------------------------------------- */
    int freq[256] = {0};

    /* Count characters of the first string */
    for (size_t i = 0; s1[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s1[i];
        if (c == ' ')               /* spaces are ignored */
            continue;
        if (c >= 'A' && c <= 'Z')   /* case‑insensitive handling */
            c = (unsigned char)(c + ('a' - 'A'));
        freq[c]++;                  /* increment count */
    }

    /* Subtract characters of the second string */
    for (size_t i = 0; s2[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s2[i];
        if (c == ' ')
            continue;
        if (c >= 'A' && c <= 'Z')
            c = (unsigned char)(c + ('a' - 'A'));
        freq[c]--;                  /* decrement count */
    }

    /* -------------------------------------------------------------------- */
    /* Determine whether the two strings are anagrams                        */
    /* -------------------------------------------------------------------- */
    const char *result = "ANAGRAM";
    for (int i = 0; i < 256; ++i) {
        if (freq[i] != 0) {
            result = "NOT_ANAGRAM";
            break;
        }
    }

    puts(result);
    return 0;
}
